persistent_memory = {}

def should_store(fact):
    # filter for what is actually worth storing
    return "preference" in fact.lower() or "always" in fact.lower()

def store_memory(user_id, fact):
    if should_store(fact):
        persistent_memory[user_id] = fact
        return True
    return False

def retrieve_memory(user_id):
    # retrieve only what's relevant, not everything stored
    return persistent_memory.get(user_id, "No stored memory.")

user_id = "user_42"

# conversation one: a preference and an irrelevant question
store_memory(user_id, "User preference: always respond in short bullet points.")
store_memory(user_id, "User asked what time it is.")

print("Stored memory after conversation one:")
print(retrieve_memory(user_id))

# the preference changes later; the old value must be overwritten
store_memory(user_id, "User preference: always respond in full paragraphs now.")
print("\nStored memory after the preference changed:")
print(retrieve_memory(user_id))
